      html: '<clr-select-container>\n  <label>Locale</label>\n  <select clrSelect name="locales" [(ngModel)]="translateService.locale">\n    @for (locale of locales; track locale[1]) {\n    <option [value]="locale[1]">{{ locale[0] }}</option>\n    }\n  </select>\n</clr-select-container>\n\n<section class="clr-mt-24px">\n  <p>\n    <strong cds-text="medium">Translated Text:</strong>\n    {{ \'hello-world\' | translate }}\n  </p>\n</section>\n\n<section class="clr-mt-24px">\n  <clr-select-container>\n    <label>DateTimeKind</label>\n    <select clrSelect name="dateTimeKind" [(ngModel)]="dateTimeFormat.dateTimeKind">\n      @for (dateTimeKind of dateTimeKinds; track dateTimeKind[1]) {\n      <option [value]="dateTimeKind[1]">{{ dateTimeKind[0] }}</option>\n      }\n    </select>\n  </clr-select-container>\n\n  <clr-select-container>\n    <label>HourFormat</label>\n    <select clrSelect name="hourFormat" [(ngModel)]="dateTimeFormat.hourFormat">\n      @for (hourFormat of hourFormats; track hourFormat[1]) {\n      <option [value]="hourFormat[1]">{{ hourFormat[0] }}</option>\n      }\n    </select>\n  </clr-select-container>\n\n  <p class="clr-mt-16px">\n    <strong cds-text="medium">Formatted Date:</strong>\n    {{ getNow() | dateTime: dateTimeFormat }}\n  </p>\n</section>\n',
      ts: "import { Component } from '@angular/core';\nimport { FormsModule } from '@angular/forms';\nimport {\n  AppfxLocale,\n  appfxMissingTranslationToken,\n  AppfxTranslateModule,\n  AppfxTranslateService,\n  AppfxTranslations,\n  appfxTranslationsToken,\n  DateTimeFormatOptions,\n  DateTimeKind,\n  HourFormat,\n} from '@clr/addons/translate';\nimport { ClrSelectModule } from '@clr/angular';\n\n@Component({\n  selector: 'app-example',\n  templateUrl: './example.component.html',\n  imports: [AppfxTranslateModule, ClrSelectModule, FormsModule],\n  providers: [\n    AppfxTranslateService,\n    {\n      provide: appfxMissingTranslationToken,\n      useValue: (translations: AppfxTranslations, locale: AppfxLocale, key: string) => {\n        return `<Missing translation for locale \"${locale}\" with key \"${key}\">`;\n      },\n    },\n    {\n      provide: appfxTranslationsToken,\n      useValue: {\n        [AppfxLocale.En]: {\n          'hello-world': 'Hello World!',\n        },\n        [AppfxLocale.Es]: {\n          'hello-world': 'Hola Mundo!',\n        },\n      },\n    },\n  ],\n})\nexport class ExampleComponent {\n  readonly locales = Object.entries(AppfxLocale);\n\n  readonly dateTimeKinds = Object.entries(DateTimeKind).filter(([key]) => Number.isNaN(Number(key)));\n  readonly hourFormats = Object.entries(HourFormat);\n\n  readonly dateTimeFormat: DateTimeFormatOptions = {\n    dateTimeKind: DateTimeKind.DateTime,\n    hourFormat: HourFormat.Hour24,\n  };\n\n  constructor(readonly translateService: AppfxTranslateService) {}\n\n  getNow(): Date {\n    return new Date();\n  }\n}\n",
